def vec(path):
    return ('<vector xmlns:android="http://schemas.android.com/apk/res/android"\n'
            '    android:width="24dp" android:height="24dp"\n'
            '    android:viewportWidth="24" android:viewportHeight="24"\n'
            '    android:tint="?attr/colorControlNormal">\n'
            '    <path android:fillColor="#FF000000" android:pathData="%s"/>\n'
            '</vector>\n' % path)

if __name__ == "__main__":
    out = sys.argv[1]
    os.makedirs(out, exist_ok=True)
    for name, d in ICONS.items():
        with open(os.path.join(out, name + ".xml"), "w") as f:
            f.write(vec(d))
    print("wrote", len(ICONS), "icons")
